CREATE TABLE IF NOT EXISTS departments(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS task_dependencies(task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,depends_on_task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,PRIMARY KEY(task_id,depends_on_task_id));
CREATE TABLE IF NOT EXISTS messages(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,task_id UUID REFERENCES tasks(id) ON DELETE SET NULL,sender_agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,receiver_agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tool_executions(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,action TEXT NOT NULL,resource TEXT,arguments JSONB NOT NULL DEFAULT '{}',status TEXT NOT NULL,result JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS notifications(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,employee_id UUID REFERENCES employees(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());